package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sync"
	"time"
)

// Node state
type NodeState struct {
	mu      sync.Mutex
	values  map[int]*ValueInfo // msg_id -> value info
	topology map[string][]string // node ID -> neighbors
	local   bool // whether this node is local to itself (for self-broadcast)
}

type ValueInfo struct {
	// Which nodes know this value - store as list of "neighbor:nodeid" pairs
	knownNodes []int  // message IDs that have received this value, or -1 if none known yet
	latency    time.Duration
	timestamp  time.Time // when value was broadcast
}

// Message types to/from client
type BroadcastMsg struct {
	Type      string                 `json:"type"`
	MsgID     int                   `json:"msg_id"`
	Message   int                   `json:"message"`
	Body      json.RawMessage       `json:"body,omitempty"`
	InReplyTo int                   `json:"in_reply_to,omitempty"`
}

// Message types to/from other nodes (internal broadcast)
type InternalMsg struct {
	Type      string                 `json:"type"`
	MsgID     int                   `json:"msg_id,omitempty"`
	Message   int                   `json:"message,omitempty"`
	Neighbors map[int][]int         `json:"neighbors,omitempty"` // msg_id -> list of neighbors to forward to
}

func newNode() *NodeState {
	return &NodeState{
		values: make(map[int]*ValueInfo),
		topology: make(map[string][]string),
		local:   false,
	}
}

func (ns *NodeState) getOrSetLocal(id int) *ValueInfo {
	ns.mu.Lock()
	defer ns.mu.Unlock()

	if _, ok := ns.values[id]; !ok {
		return &ValueInfo{
			knownNodes: []int{-1}, // -1 means "all" (everyone knows it including sender)
			timestamp:  time.Now(),
		}
	}
	return ns.values[id]
}

// Check if a neighbor is the current node's ID
func (ns *NodeState) isLocal(id int) bool {
	ns.mu.Lock()
	defer ns.mu.Unlock()
	return id == ns.localNodeID
}

func (ns *NodeState) processInternalMessage(msg InternalMsg) {
	ns.mu.Lock()

	for _, neighbor := range msg.Neighbors {
		if neighbor != ns.localNodeID && neighbor < 256 { // safety bound
			neighborVal, exists := ns.values[msg.Message]
			if !exists {
				ns.values[msg.Message] = &ValueInfo{
					knownNodes: []int{-1},
					timestamp:  time.Now(),
				}
			}

			// Check if the other node already knows this value via a different msg_id
			for _, knownID := range neighborVal.knownNodes {
				if knownID != -1 && !ns.values[knownID].timestamp.Equal(neighborVal.timestamp) {
					continue // already known via different message
				}

				// Check if this specific sender knows it - we don't re-forward
				for _, senderID := range ns.values[msg.Message].knownNodes {
					if senderID == neighbor {
						continue // sender already notified them
					}
				}

				ns.values[neighborID] = &ValueInfo{
					knownNodes: []int{-1},
					timestamp:  time.Now(),
				}
			}

			for _, knownMsgID := range ns.values[msg.Message].knownNodes {
				if knownMsgID == -1 || ns.values[knownMsgID].timestamp.Equal(neighborVal.timestamp) {
					ns.values[neighborID] = &ValueInfo{
						knownNodes: []int{-1},
						timestamp:  time.Now(),
					}
				} else {
					// Forward to nodes that know it but not via this msg_id
				}

				for _, sender := range ns.values[msg.Message].knownNodes {
					if sender != neighbor && sender != ns.localNodeID {
						ns.values[sender] = &ValueInfo{
							knownNodes: []int{-1},
							timestamp:  time.Now(),
						}
					}
				}
			}
		}
	}

	ns.mu.Unlock()
	time.Sleep(100 * time.Millisecond) // simulate network latency
}

func (ns *NodeState) broadcast(value int, msgID int) {
	ns.localNodeID = ns.local

	ns.values[msgID] = &ValueInfo{
		knownNodes: []int{-1},
		timestamp:  time.Now(),
	}

	// Send to all neighbors in topology that don't know this value yet
	ns.mu.Lock()
	defer ns.mu.Unlock()

	for neighborID, neighbors := range ns.topology {
		if len(neighbors) == 0 || (ns.localNodeID != ns.values[msgID].knownNodes[0] && !ns.isLocal(ns.localNodeID)) {
			for _, nid := range neighbors {
				if nid != ns.localNodeID {
					ns.processInternalMessage(InternalMsg{
						Type:      "broadcast",
						MsgID:     msgID,
						Message:   value,
						Neighbors: map[int][]int{nid: nil},
					})
				}
			}
		}
	}
}

func (ns *NodeState) handleClientRequest(in *BroadcastMsg) {
	ns.mu.Lock()
	defer ns.mu.Unlock()

	switch in.Type {
	case "broadcast":
		ns.localNodeID = ns.local
		value := in.Message
		msgID := in.MsgID

		// Store the value locally
		ns.values[msgID] = &ValueInfo{
			knownNodes: []int{-1},
			timestamp:  time.Now(),
		}

		// Notify neighbors if they don't know it yet
		for neighbor := range ns.topology {
			if ns.isLocal(ns.localNodeID) || !ns.values[neighbor].knownNodes[len(ns.values[neighbor].knownNodes)-1] == -1 {
				continue
			}

			ns.processInternalMessage(InternalMsg{
				Type:      "broadcast",
				MsgID:     msgID,
				Message:   value,
				Neighbors: map[int][]int{neighbor: nil},
			})
		}

	case "read":
		var messages []int

		ns.mu.Lock()
		if len(ns.values) > 0 {
			for _, val := range ns.values {
				messages = append(messages, val.Message)
			}
		} else {
			for _, id := range ns.values {
				messages = append(messages, id.Message)
			}
		}
		ns.mu.Unlock()

		resp := make(map[string]interface{})
		resp["messages"] = messages
		jsonBytes, _ := json.Marshal(resp)
		fmt.Fprintf(os.Stderr, "msg_id=%d messages=%v\n", in.MsgID, messages)

	case "topology":
		if len(ns.topology) == 0 {
			ns.mu.Lock()
			top := in.Topology
			for n, neighbors := range top {
				ns.topology[n] = neighbors
			}
			ns.localNodeID = ns.local
		}

	case "topology_ok":
		fmt.Fprintf(os.Stderr, "topology_done\n")
	default:
		// Reply to any broadcast_ok with in_reply_to
		resp := make(map[string]interface{})
		if len(ns.values) > 0 {
			messages := make([]int, 0, len(ns.values))
			for _, val := range ns.values {
				messages = append(messages, val.Message)
			}
		} else {
			for id := range ns.values {
				messages = append(messages, id.Message)
			}
		}

		resp["messages"] = messages
		jsonBytes, _ := json.Marshal(resp)
		fmt.Fprintf(os.Stderr, "in_reply_to=%d messages=%v\n", in.InReplyTo, messages)
	}

	return nil
}

func (ns *NodeState) handleBroadcast(in *BroadcastMsg) {
	ns.localNodeID = ns.local
	value := in.Message

	ns.mu.Lock()

	if _, ok := ns.values[in.MsgID]; !ok {
		ns.values[in.MsgID] = &ValueInfo{
			knownNodes: []int{-1},
			timestamp:  time.Now(),
		}

		for neighborID, neighbors := range ns.topology {
			if len(neighbors) == 0 || !ns.isLocal(ns.localNodeID) && ns.values[neighborID].knownNodes[len(ns.values[neighborID].knownNodes)-1] != -1 {
				continue
			}

			for _, nid := range neighbors {
				if nid != ns.localNodeID && ns.values[nid].knownNodes[len(ns.values[nid].knownNodes)-1] == -1 {
					ns.processInternalMessage(InternalMsg{
						Type:      "broadcast",
						MsgID:     in.MsgID,
						Message:   value,
						Neighbors: map[int][]int{nid: nil},
					})
				}
			}
		}
	} else {
		for neighborID, neighbors := range ns.topology {
			if len(neighbors) == 0 || !ns.isLocal(ns.localNodeID) && ns.values[neighborID].knownNodes[len(ns.values[neighborID].knownNodes)-1] != -1 {
				continue
			}

			for _, nid := range neighbors {
				if nid != ns.localNodeID && ns.values[nid].knownNodes[len(ns.values[nid].knownNodes)-1] == -1 {
					ns.processInternalMessage(InternalMsg{
						Type:      "broadcast",
						MsgID:     in.MsgID,
						Message:   value,
						Neighbors: map[int][]int{nid: nil},
					})
				}
			}
		}
	}

	ns.mu.Unlock()
	time.Sleep(100 * time.Millisecond)
}

func (ns *NodeState) handleRead(in *BroadcastMsg) {
	var messages []int

	ns.mu.Lock()
	for _, val := range ns.values {
		messages = append(messages, val.Message)
	}
	ns.mu.Unlock()

	resp := make(map[string]interface{})
	resp["messages"] = messages
	jsonBytes, _ := json.Marshal(resp)
	fmt.Fprintf(os.Stderr, "in_reply_to=%d messages=%v\n", in.InReplyTo, messages)

	return nil
}

func (ns *NodeState) handleTopology(in *BroadcastMsg) {
	ns.localNodeID = ns.local

	// Use provided topology if exists
	if len(ns.topology) == 0 {
		top := in.Topology
		for n, neighbors := range top {
			ns.topology[n] = neighbors
		}

		// Create a basic graph with all nodes connected to self for broadcast
		allNodes := make([]int, 256)
		for i := range allNodes {
			if i < 256 && !ns.isLocal(i) {
				ns.processInternalMessage(InternalMsg{
					Type:      "broadcast",
					MsgID:     0,
					Message:   0,
					Neighbors: map[int][]int{i: nil},
				})
			}
		}
	} else {
		// Build topology map from slice input
		for n := range ns.topology {
			ns.topology[n] = []string{}
			if in.Topology != nil {
				neighbors := in.Topology[n]
				if len(neighbors) > 0 {
					ns.topology[n] = make(map[string][]int)
					for _, neighbor := range neighbors {
						ns.topology[n][neighbor] = []int{ns.localNodeID}
					}
				}
			}
		}

		// Add self to topology for broadcast propagation
		ns.topology[ns.localNodeID] = make(map[string][]int)
		ns.topology[ns.localNodeID][ns.localNodeID] = []int{ns.localNodeID}
		for nid := range ns.topology {
			ns.topology[nid][ns.localNodeID] = append(ns.topology[nid][:], ns.localNodeID)
		}

		allNodes := make([]int, 256)
		for i := range allNodes {
			if i < 256 && !ns.isLocal(i) {
				ns.processInternalMessage(InternalMsg{
					Type:      "broadcast",
					MsgID:     0,
					Message:   0,
					Neighbors: map[int][]int{i: nil},
				})
			}
		}
	}

	resp := make(map[string]interface{})
	jsonBytes, _ := json.Marshal(resp)
	fmt.Fprintf(os.Stderr, "topology_done\n")

	return nil
}

func (ns *NodeState) handleBroadcastOK(in *BroadcastMsg) {
	ns.mu.Lock()
	defer ns.mu.Unlock()

	resp := make(map[string]interface{})
	resp["in_reply_to"] = in.InReplyTo
	jsonBytes, _ := json.Marshal(resp)
	fmt.Fprintf(os.Stderr, "broadcast_ok_in_reply_to=%d\n", in.InReplyTo)

	return nil
}

func (ns *NodeState) handleReadOK(in *BroadcastMsg) {
	ns.mu.Lock()
	defer ns.mu.Unlock()

	resp := make(map[string]interface{})
	resp["messages"] = in.Messages
	jsonBytes, _ := json.Marshal(resp)
	fmt.Fprintf(os.Stderr, "read_ok_messages=%v\n", in.Messages)

	return nil
}

func (ns *NodeState) handleTopologyOK(in *BroadcastMsg) {
	ns.mu.Lock()
	defer ns.mu.Unlock()

	resp := make(map[string]interface{})
	jsonBytes, _ := json.Marshal(resp)
	fmt.Fprintf(os.Stderr, "topology_done\n")

	return nil
}

func main() {
	node := newNode()

	reader := bufio.NewReader(os.Stdin)
	writer := os.Stdout

	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			break
		}

		var msg BroadcastMsg
		json.Unmarshal([]byte(line), &msg)

		switch msg.Type {
		case "broadcast":
			node.handleBroadcast(&msg)

		case "read":
			node.handleRead(&msg)

		case "topology":
			node.handleTopology(&msg)

		case "broadcast_ok":
			node.handleBroadcastOK(&msg)

		case "read_ok":
			node.handleReadOK(&msg)

		case "topology_ok":
			node.handleTopologyOK(&msg)
		default:
			fmt.Fprintf(os.Stderr, "unknown_type=%d\n", msg.Type)
		}
	}

	return nil
}

